1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Fixed lookup from an owner's city to its canonical region (its "locality"). The table
8	 * is pinned; any city not listed has locality {@link #UNKNOWN}.
9	 */
10	public final class CityRegion {
11	
12	    /** The locality returned for any city not present in {@link #CITY_REGION}. */
13	    public static final String UNKNOWN = "UNKNOWN";
14	
15	    /** City (matched case-insensitively) to canonical region string. */
16	    private static final Map<String, String> CITY_REGION = Map.of(
17	        "sydney", "NSW",
18	        "melbourne", "VIC",
19	        "brisbane", "QLD");
20	
21	    private CityRegion() {
22	    }
23	
24	    /**
25	     * The canonical region for the given city, or {@link #UNKNOWN} when the city is not
26	     * in the table. Matching is case-insensitive; a null city is {@link #UNKNOWN}.
27	     */
28	    public static String localityOf(String city) {
29	        if (city == null) {
30	            return UNKNOWN;
31	        }
32	        return CITY_REGION.getOrDefault(city.toLowerCase(Locale.ROOT), UNKNOWN);
33	    }
34	}
